  classification(video, objOrCallback = null, callback) {
    let cb;

    this.usageType = "classifier";

    if (typeof objOrCallback === "object") {
      Object.assign(this.config, objOrCallback);
    } else if (typeof objOrCallback === "function") {
      cb = objOrCallback;
