            nose: landmarks.getNose(),
            leftEye: landmarks.getLeftEye(),
            leftEyeBrow: landmarks.getLeftEyeBrow(),
            rightEye: landmarks.getRightEye(),
            rightEyeBrow: landmarks.getRightEyeBrow(),
            jawOutline: landmarks.getJawOutline(),
